# ── 3부 「소년 다윗」(8~11장, 삼상 16–20장) — gen7.py가 읽어 실행한다. 글자는 전부 원문 파일에서 자른다 ──
def sub(c, n, a, e=None):
    t = v(S, c, n); i = t.index(a); s = t[i:(t.rindex(e) + len(e)) if e else i + len(a)]
    assert s in t; return s
